INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (1, 'Pollo Guisado', '45 min', '1. Sella el pollo en una olla caliente. 2. Agrega cebolla, ajo, pimientos. 3. Incorpora tomate, comino, orégano. 4. Añade caldo de pollo y deja cocinar 30 min. 5. Sirve con arroz.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRcSweYOFNc-JFdbmWmYye0FPD1s7eFdrMdNSMdPlRA8g&s=10', 2);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (2, 'Pollo Asado', '1 hora 20 min', '1. Mezcla ajo, orégano, comino, naranja agria, sal y pimienta. 2. Marina el pollo por 2 horas. 3. Hornea a 200°C por 1 hora. 4. Deja reposar y sirve.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQmIqfBf60kaziYXq79sQmek38oVayCxcM9ZAAcI3zKoQ&s=10', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (4, 'Ensalada César', '20 min', '1. Lava y corta la lechuga. 2. Prepara la salsa: mezcla mayonesa, ajo, anchoas, mostaza, limón. 3. Mezcla todo con crutones y queso parmesano.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTeLvzbM4JbpfQPaXFUhLZUYFuZtJUrYGgsbUNEEAfTPQ&s=10', 1);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (5, 'Arroz con Pollo', '45 min', 'Cocinar pollo con soffritto de vegetales, incorporar arroz y caldo hasta granear.', 'https://www.recetasnestle.com.ec/sites/default/files/srh_recipes/7948f17d96e25b77a0aeb23641795c5e.jpg', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (6, 'Pastel de Chocolate', '45 min', 'Bizcocho esponjoso de cacao cubierto de ganache de chocolate.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=800&q=80', 25);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (7, 'Tacos hondureños', '30 min', '1. Cocina la carne molida con cebolla y ajo. 2. Sazona con comino, chile en polvo, sal. 3. Calienta las tortillas. 4. Sirve con cilantro, cebolla, salsa.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRBfe7VMGwSqZyzolMp5mdPeCXVor3iMzWc2bmLM3jWMg&s=10', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (9, 'Cordon Blue', '50 min', '1. Aplana las pechugas de pollo. 2. Coloca jamón y queso en el centro, enrolla y cierra con palillos. 3. Pasa por harina, huevo y pan rallado. 4. Fríe en aceite caliente hasta dorar o hornea a 200°C por 25 min.', 'data:image/jpeg;base64,', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (10, 'Espaguetis con salsa bolognesa', '40 min', '1. Sofríe cebolla, ajo, zanahoria, apio. 2. Añade carne molida, cocina hasta dorar. 3. Agrega vino tinto (opcional) y tomate triturado. 4. Cocina a fuego lento 20 min. 5. Cocina los espaguetis según instrucciones. 6. Mezcla y sirve con queso parmesano.', 'https://images.unsplash.com/photo-1622973536968-3ead9e780960?auto=format&fit=crop&w=800&q=80', 2);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (12, 'Sopa de tortilla', '40 min', 'Caldo de tomate y chile guajillo servido con tortillas fritas, aguacate y crema.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQFFJ5lU-BaxbgAwZwg96wRvdT0TU2GtKbtZ5a7G7ejXQ&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (13, 'Tacos mexicanos', '40 min', '1. Prepara la carne: cocina carne molida con cebolla, ajo, comino, sal. 2. Calienta las tortillas y rellena con la carne. 3. Fríe los tacos doblados hasta que estén crujientes. 4. Sirve con repollo rallado, salsa de tomate, queso rallado y crema.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQSXbuOuEaneB_EzE6r_zyGK5OucibBxapPZEp-UWsMAQ&s=10', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (15, 'Nachos con chili', '30 min', '1. Prepara el chili: sofríe cebolla, ajo, carne molida, añade tomate, frijoles, chile en polvo, comino. 2. Coloca los nachos en una bandeja, cubre con el chili caliente. 3. Añade queso rallado y gratina 5 min. 4. Sirve con guacamole, crema agria, jalapeños.', 'https://images.unsplash.com/photo-1513456852971-30c0b8199d4d?auto=format&fit=crop&w=800&q=80', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (17, 'Espaguetis blancos (salsa cremosa)', '25 min', '1. Cocina los espaguetis según instrucciones. 2. Prepara la salsa: derrite mantequilla, añade ajo, crema de leche, queso parmesano, nuez moscada. 3. Mezcla la pasta con la salsa. 4. Opcional: agrega pollo o champiñones.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ7ECx2deOvYP85cWgetkGoNxS0sqb7qcBH0Rpm6SyQ_Q&s', 2);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (18, 'Marmahon', '30 min', '1. Prepara masa de maíz y forma tortillas gruesas. 2. Cocina en comal. 3. Rellena con frijoles molidos, carne molida sazonada, queso rallado y crema. 4. Dobla como quesadilla.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSwy4xg68JJKZq_uQRwxnCp0OyvnpVeAoM7vJzi2jghYg&s=10', 1);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (20, 'Momias de pollo enrolladas con tocino', '40 min', '1. Corta las pechugas de pollo en tiras. 2. Envuelve cada tira con tocino. 3. Hornea a 200°C por 25 min. 4. Opcional: barniza con salsa BBQ.', 'data:image/jpeg;base64,', 3);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (21, 'Vegetales al vapor', '20 min', 'Cocinar los vegetales mixtos al vapor hasta que estén al dente. Sazonar con mantequilla, sal y pimienta.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQsmtGPBrlYeYQmnMbvqCiujA_PJAoiqhNNxOxL1-gbMw&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (22, 'Ensalada de lechuga', '10 min', 'Lavar y trocear lechuga fresca. Aderezar con aceite de oliva, limón y sal.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTQjchOfCIF8Q1C5ypPNG1QBShIIFHVaUmaMxF37hCNxA&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (23, 'Ensalada con cherry', '15 min', 'Mezclar lechugas variadas, tomates cherry cortados a la mitad, queso y vinagreta balsámica.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS0beXAfwYdo6ChhF_fQR5bxzJm901wlEWItEh3FvBvrg&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (24, 'Ensalada de tomate', '10 min', 'Rebanar tomates jugosos, agregar cebolla morada, orégano, sal y aceite de oliva.', 'data:image/jpeg;base64,', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (25, 'Ensalada de pepino', '10 min', 'Cortar pepinos en rodajas finas, marinar con vinagre, limón, pimienta y sal.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSSF4DqLYNdsGtpeNHirwrKt779nvRyfw0Aw0tYrl1QqQ&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (26, 'Ensalada de repollo con limón', '15 min', 'Rallar el repollo finamente, mezclar con abundante jugo de limón, sal y culantro.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSGnCxFiB-XVEJY0KCcJQpqDyT97bGlEtRJP3np-IH0TA&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (27, 'Ensalada de repollo con mayonesa', '15 min', 'Mezclar repollo rallado, zanahoria rallada, mayonesa, toque de azúcar y vinagre.', 'data:image/jpeg;base64,', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (28, 'Ensalada de remolacha con huevo', '25 min', 'Cocer remolachas y huevos. Cortar en cubos y condimentar con mayonesa o vinagreta.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTcywvQZiQmxJ66lrIz9dDG7jylGEqhGk_LhZhuDMuUFg&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (29, 'Ensalada de papa con huevo', '30 min', 'Hervir papas y huevos duros. Mezclar en cubos con mayonesa, apio picado, sal y pimienta.', 'data:image/jpeg;base64,', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (30, 'Coliflor en margarina', '20 min', 'Cocer ramilletes de coliflor. Saltear en sartén con abundante margarina y pimienta.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTn-lReLPf2_5A1L3xsC8utUUmFWrKhYUIs6HEFIN_A2A&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (31, 'Brócoli cocido', '15 min', 'Blanquear el brócoli en agua hirviendo con sal durante 5 min. Servir con un chorrito de aceite de oliva.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTO1pEukStBeG5CCPlwxlBUvts4by-5AGQp860KvbwgPw&s=10', 22);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (32, 'Puré de papa', '25 min', 'Hervir papas peladas, triturar caliente con mantequilla, leche, sal y nuez moscada.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRlnCjIP1LbmQnyhAi2XIT09-spUasuRlnX8dhyDr3e_w&s=10', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (33, 'Papa al horno con jamón y queso', '45 min', 'Hornear la papa, ahuecar y rellenar con crema, jamón picado y queso mozzarella derretido.', 'data:image/jpeg;base64,', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (35, 'Papa cocida y frita en rodajas grandes', '30 min', 'Hervir papas en rodajas gruesas y luego freír en aceite caliente hasta dorar por ambos lados.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT6Fa86KFnG61z9k8JQAXjcnzc3k19EymUXsLN2A0s10g&s=10', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (36, 'Coditos con jamón', '20 min', 'Cocer pasta de coditos, mezclar con crema de leche, jamón en cubos y queso rallado.', 'https://images.unsplash.com/photo-1550304943-4f24f54ddde9?auto=format&fit=crop&w=800&q=80', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (39, 'Pastelitos de carne molida', '35 min', 'Rellenar discos de masa con carne molida sazonada y freír hasta dorar.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQNn_7Ol-5PePTotC9ppTGv7I_gtwHi4lsovJun9bzpKg&s', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (41, 'Enchiladas de pollo', '40 min', 'Tortillas fritas cubiertas con pollo desmenuzado, repollo, huevo duro, queso y salsa roja.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSVF7aRivDqOl0AEwhAIjSrKhYFwMxCESNoMw-w2IXT2g&s=10', 24);
