INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (44, 'Lasagna de carne', '1 hora', 'Láminas de pasta alternadas con bolognesa, salsa bechamel y queso mozzarella al horno.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRhhDiIQH3-aqungTpB5LbJCfvkxfEguRLqyNnIcqjDLA&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (45, 'Canelones de pollo', '50 min', 'Canelones rellenos de pollo cremoso, gratinados con salsa blanca y queso.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTW5nuBAfVJ5B7NRYxUVTfKPyBKacrSLjRXOFhLV1JDaw&s=10', 24);
