INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (47, 'Arroz blanco', '20 min', 'Sofreír arroz con ajo y cebolla, añadir agua hirviendo con sal y cocer a fuego lento.', 'https://images.unsplash.com/photo-1516684732162-798a0062be99?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (49, 'Carne molida', '25 min', 'Guisar carne molida de res con tomates, papas en cubos, cebolla y comino.', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?auto=format&fit=crop&w=800&q=80', 24);
