INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (53, 'Arroz amarillo', '25 min', 'Sazonar el arroz con achiote o azafrán, maíz dulce y arvejas.', 'https://www.recetasnestle.com.ec/sites/default/files/styles/recipe_detail_desktop_new/public/srh_recipes/1085d3b9536f88cd0f583a2cc86d97fc.webp?itok=8sEproi1', 25);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (54, 'Arroz jardinero', '30 min', 'Arroz variado con zanahorias, judías verdes, maíz, pimientos y hierbas.', 'https://images.unsplash.com/photo-1596560548464-f010549b84d7?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (56, 'Pollo agridulce', '35 min', 'Pollo frito salteado en salsa agridulce con piña, cebolla y pimientos.', 'data:image/jpeg;base64,', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (57, 'Carne guisada', '50 min', 'Carne de res tierna guisada con papas, zanahorias y salsa de tomate concentrada.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRax__EbPCfnwB7NTpXF4iI8aPHn6Fi4PZI8s6MsB7W1Q&s=10', 24);
