INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (62, 'Chop suey casero', '30 min', 'Vegetales salteados finamente con pollo, carne de res, salsa soya y fideos.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRGUP0sg37p5c1vNy6wI12O8tF17BhFHo2boD5WvaZB-Q&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (63, 'Sopa Maggi', '15 min', 'Sopa de fideos o tortilla sazonada caliente con verdura fresca.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRqxmiOuyVyFGMMxRV0HRKSk2YbvEbd5RVQ2tzWpYrpww&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (64, 'Marmahón', '35 min', 'Pasta de marmahón guisada con vegetes, pechuga de pollo y especias orientales.', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (65, 'Flan de Vainilla', '50 min', 'Postre cremoso de huevo y leche cocido a baño maría sobre caramelo fluido.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRd2nm3G1QqXAev4E0KzuV7riNPxcgmNhRWToQVMjnu7A&s=10', 25);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (66, 'Tortilla española', '30 min', 'Freír papas y cebollas en rodajas finas, mezclar con huevos batidos y cuajar en la sartén por ambos lados.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQs3QM8pKrvk6b3XFx4_kI8kaiS2ZIUH9hDbzEFYZhUuA&s=10', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (67, 'Hamburguesa', '20 min', 'Asar la tortita de carne a la parrilla, armar en pan de hamburguesa con queso, lechuga, tomate y salsas.', 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (68, 'Hotdog', '15 min', 'Cocer la salchicha, servir en pan de hot dog con mostaza, ketchup, mayonesa y cebolla picada.', 'https://images.unsplash.com/photo-1619740455993-9e612b1af08a?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (69, 'Sánguches', '15 min', 'Tostar pan de molde, rellenar con jamón, queso, lechuga, tomate, mayonesa y mantequilla.', 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (70, 'Sopa de capirotada', '45 min', 'Prepara bolitas de queso frito (capirotadas) y cocina en un rico caldo sazonado de tomates y especias.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR02lNVJcDwK3MPQ0roig_yuet92zNLctwcU1NmGV_8bQ&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (71, 'Tortillas con quesillo', '15 min', 'Calentar tortillas de maíz con abundante quesillo fundido en medio hasta que se derrita.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSBxUHJn8GqBPKIXYvD-1Q68RzQcun5GKoScxJOVQEEgQ&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (72, 'Panqueques', '20 min', 'Mezclar harina, leche, huevo y mantequilla. Cocinar discos en la sartén y servir con miel.', 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (73, 'Baleadas', '20 min', 'Tortilla de harina recién hecha rellena de frijoles fritos, mantequilla y queso duro rallado.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJFV-xn3o7Ut_OpRr5lDgdUiaxzL37xywF5-pamNjjiA&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (75, 'Papilla de manzana y banano', '15 min', 'Cocer manzana al vapor y triturar junto con banano maduro fresco.', 'https://images.unsplash.com/photo-1568899466260-b6d4e56e8e42?auto=format&fit=crop&w=800&q=80', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (77, 'Papilla de avena', '15 min', 'Cocer avena en agua con trozos de pera hasta que esté muy tierna y triturar.', 'data:image/jpeg;base64,', NULL);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (78, 'Huevos rancheros', '15 min', 'Huevos estrellados sobre tortillas de maíz fritas, cubiertos con salsa roja picante y frijoles.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSGHzoYsh0uquka39YjM5Qq5Zw5Qdl8m1azaME44RYbqg&s=10', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (79, 'Huevo estrellado', '10 min', 'Cocinar huevos a la sartén con yema tierna, sazonados con sal y pimienta negra.', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (80, 'Huevo en omelette', '15 min', 'Batir huevos, doblar en la sartén con relleno de queso, jamón y pimientos finamente picados.', 'https://images.unsplash.com/photo-1510693206972-df098062cb71?auto=format&fit=crop&w=800&q=80', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (81, 'Huevo con chorizo', '15 min', 'Sofreír chorizo desmenuzado, agregar huevos batidos y revolver hasta cuajar.', 'data:image/jpeg;base64,', 24);
INSERT INTO `recetas` (`id`, `nombre`, `tiempo`, `instrucciones`, `imagen`, `categoria_id`) VALUES (82, 'Huevo con hotdog', '15 min', 'Saltear rodajas de salchicha de hotdog, añadir huevos revueltos y dorar al gusto.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSfjcTN52cb26HC69oQSJa1nRENf77gR4i5p8bhJ0Wssw&s=10', 24);
